package main

import (
	"bytes"
	"encoding/json"
	"html/template"
	"path/filepath"
	"strings"
)

// Only encoding/json output enters JavaScript. Its HTML escaping remains on;
// original operational text is rendered into the DOM with textContent.
func renderDashboard(snapshot DashboardSnapshot, refreshSeconds int) ([]byte, error) {
	instance := strings.TrimSpace(snapshot.InstanceName)
	if instance == "" {
		instance = filepath.Base(filepath.Clean(snapshot.RunFolder))
		if instance == "." || instance == string(filepath.Separator) || instance == "" {
			instance = "MetaThought"
		}
	}
	displayTitle := strings.TrimSpace(snapshot.DisplayTitle)
	if displayTitle == "" {
		displayTitle = dashboardDisplayTitle(instance, snapshot.Objective)
	}
	encoded, err := json.Marshal(snapshot)
	if err != nil {
		return nil, err
	}
	page, err := template.New("dashboard").Parse(dashboardHTML)
	if err != nil {
		return nil, err
	}
	var output bytes.Buffer
	err = page.Execute(&output, struct {
		Snapshot     template.JS
		Refresh      int
		Instance     string
		DisplayTitle string
	}{Snapshot: template.JS(encoded), Refresh: refreshSeconds, Instance: instance, DisplayTitle: displayTitle})
	return output.Bytes(), err
}

